int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int b, p;
    cin >> b >> p;
    vector<char> grid(b * p);
    int start = 0, end = 0;
    for (int i = 0; i < b * p; i++) {
        cin >> grid[i];
        if (grid[i] == 'Q') start = i;
        if (grid[i] == 'W') end = i;
    }
    const int dr[4] = {-1, 1, 0, 0}, dc[4] = {0, 0, -1, 1};
    // State = (cell, last direction, turns used), encoded as (cell * 4 + dir) * 3 + turns.
    vector<char> seen((size_t)b * p * 12, 0);
    vector<int> queue;
    // Expands one state; old = -1 marks the start, where the first move is not a turn.
    auto expand = [&](int cell, int old, int turns) {
        int r = cell / p, c = cell % p;
        for (int d = 0; d < 4; d++) {
            int nt = turns + (old != -1 && old != d);
            int nr = r + dr[d], nc = c + dc[d];
            if (nt > 2 || nr < 0 || nr >= b || nc < 0 || nc >= p || grid[nr * p + nc] == 'x') continue;
            int next = nr * p + nc, state = (next * 4 + d) * 3 + nt;
