import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static int b, p, end, tail;
    static byte[] grid, seen;
    static int[] queue;
    static final int[] DR = {-1, 1, 0, 0}, DC = {0, 0, -1, 1};

    // Expands one state; old = -1 marks the start, where the first move is not a turn.
    static boolean expand(int cell, int old, int turns) {
        int r = cell / p, c = cell % p;
        for (int d = 0; d < 4; d++) {
            int nt = turns + (old != -1 && old != d ? 1 : 0);
            int nr = r + DR[d], nc = c + DC[d];
            if (nt > 2 || nr < 0 || nr >= b || nc < 0 || nc >= p || grid[nr * p + nc] == 'x') continue;
            int next = nr * p + nc, state = (next * 4 + d) * 3 + nt;
            if (seen[state] != 0) continue;
            if (next == end) return true;
            seen[state] = 1;
            queue[tail++] = state;
        }
        return false;
    }

    public static void main(String[] args) throws IOException {
        b = nextInt();
        p = nextInt();
        grid = new byte[b * p];
        int start = 0;
        for (int i = 0; i < b * p; i++) {
            int c = read();
            while (c <= ' ') c = read();
            grid[i] = (byte) c;
            if (c == 'Q') start = i;
            if (c == 'W') end = i;
        }
        // State = (cell, last direction, turns used), encoded as (cell * 4 + dir) * 3 + turns.
        seen = new byte[b * p * 12];
        queue = new int[b * p * 12];
        boolean found = expand(start, -1, 0);
        for (int head = 0; !found && head < tail; head++) {
            int s = queue[head];
            found = expand(s / 12, s / 3 % 4, s % 3);
        }
        System.out.println(found ? "DRIVE!" : "DON'T DRIVE!");
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	b, p := int(nextInt()), int(nextInt())
	grid := make([]byte, b*p)
	start, end := 0, 0
	for i := range grid {
		skip()
		grid[i] = data[pos]
		pos++
		if grid[i] == 'Q' {
			start = i
		}
		if grid[i] == 'W' {
			end = i
		}
	}
	dr := [4]int{-1, 1, 0, 0}
	dc := [4]int{0, 0, -1, 1}
	// State = (cell, last direction, turns used), encoded as (cell*4 + dir)*3 + turns.
	seen := make([]bool, b*p*12)
	queue := make([]int32, 0, 1024)
	// expand returns true when W is reached; old = -1 marks the start, where the first move is not a turn.
	expand := func(cell, old, turns int) bool {
		r, c := cell/p, cell%p
		for d := 0; d < 4; d++ {
			nt := turns
			if old != -1 && old != d {
				nt++
			}
			nr, nc := r+dr[d], c+dc[d]
			if nt > 2 || nr < 0 || nr >= b || nc < 0 || nc >= p || grid[nr*p+nc] == 'x' {
				continue
			}
			next := nr*p + nc
			state := (next*4+d)*3 + nt
			if seen[state] {
				continue
			}
			if next == end {
				return true
			}
			seen[state] = true
			queue = append(queue, int32(state))
		}
		return false
	}
	found := expand(start, -1, 0)
	for head := 0; !found && head < len(queue); head++ {
		s := int(queue[head])
		found = expand(s/12, s/3%4, s%3)
	}
	if found {
		fmt.Println("DRIVE!")
	} else {
		fmt.Println("DON'T DRIVE!")
	}
}
